def forms(l, c):
    if l == 'ا': return [['ا', 'отдельно'], ['ـا', 'в конце']]
    if not c: return [[l, 'отдельно'], ['ـ' + l, 'в конце']]
    return [[l, 'отдельно'], [l + 'ـ', 'в начале'], ['ـ' + l + 'ـ', 'в середине'], ['ـ' + l, 'в конце']]

